# 07_pancancer_mutation_rewiring.R
#
# Classify pan-cancer mutation-associated rewiring from the
# mutation-stratified co-abundance results generated by script 01.
#
# Only benign and pathogenic missense mutations are analyzed.
#
# Mutation-associated rewiring is defined using the nominal
# interaction-term P value:
#
#   P < 0.05
#
# Direction:
#
#   WT positive association
#     interaction estimate > 0  -> Strengthening
#     interaction estimate < 0  -> Weakening
#
#   WT negative association
#     interaction estimate < 0  -> Strengthening
#     interaction estimate > 0  -> Weakening
#
# Input:
#   results/exprs.cor.lm.all_genes.partners.wt_only.am_class.txt
#
# Outputs:
#   results/mutation_rewiring/
#     pancancer_mutation_rewiring_edges.tsv
#     pancancer_significant_rewiring_edges.tsv
#     pancancer_mutation_rewiring_summary.tsv
#     pancancer_significant_rewiring_summary.tsv


library(data.table)


# -------------------------------------------------------------------------
# 1. Parameters
# -------------------------------------------------------------------------

r_cut <- 0.5
fdr_cut <- 0.05
interaction_p_cut <- 0.05


# -------------------------------------------------------------------------
# 2. Paths
# -------------------------------------------------------------------------

input_file <- file.path(
  "results",
  "exprs.cor.lm.all_genes.partners.wt_only.am_class.txt"
)

output_dir <- file.path(
  "results",
  "mutation_rewiring"
)

dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)

edge_output_file <- file.path(
  output_dir,
  "pancancer_mutation_rewiring_edges.tsv"
)

significant_edge_output_file <- file.path(
  output_dir,
  "pancancer_significant_rewiring_edges.tsv"
)

summary_output_file <- file.path(
  output_dir,
  "pancancer_mutation_rewiring_summary.tsv"
)

significant_summary_output_file <- file.path(
  output_dir,
  "pancancer_significant_rewiring_summary.tsv"
)


# -------------------------------------------------------------------------
# 3. Load pan-cancer mutation-stratified results from script 01
# -------------------------------------------------------------------------

res_cor <- fread(
  input_file,
  header = TRUE
)


# -------------------------------------------------------------------------
# 4. Check required columns
# -------------------------------------------------------------------------

required_columns <- c(
  "query",
  "query_refseq",
  "mutation",
  "target",
  "target_refseq",
  "wt_n",
  "mut_n",
  "wt_cor_r",
  "wt_cor_p_adj",
  "mut_cor_r",
  "mut_cor_p_adj",
  "x_Estimate",
  "x_group_Estimate",
  "x_group_StdError",
  "x_group_Pr.t.",
  "int_p_adj"
)

missing_columns <- setdiff(
  required_columns,
  colnames(res_cor)
)

if (length(missing_columns) > 0) {
  stop(
    "Missing required columns: ",
    paste(
      missing_columns,
      collapse = ", "
    )
  )
}


# -------------------------------------------------------------------------
# 5. Retain benign and pathogenic mutation classes
#
# Ambiguous AlphaMissense calls are not used in this downstream analysis.
# -------------------------------------------------------------------------

res_cor <- res_cor[
  mutation %chin% c(
    "benign",
    "pathogenic"
  )
]


# -------------------------------------------------------------------------
# 6. Define WT baseline association
# -------------------------------------------------------------------------

res_cor[
  ,
  baseline_association := fcase(
    wt_cor_r > r_cut &
      wt_cor_p_adj < fdr_cut,
    "Positive",

    wt_cor_r < -r_cut &
      wt_cor_p_adj < fdr_cut,
    "Negative",

    default = "n.s."
  )
]


# -------------------------------------------------------------------------
# 7. Keep baseline positive and negative associations
#
# Strengthening/weakening has a directional interpretation only when
# a significant WT baseline association is present.
# -------------------------------------------------------------------------

res_cor <- res_cor[
  baseline_association %chin%
    c(
      "Positive",
      "Negative"
    )
]


# -------------------------------------------------------------------------
# 8. Calculate mutation-associated changes
# -------------------------------------------------------------------------

res_cor[
  ,
  mutation_class := fcase(
    mutation == "benign",
    "Benign",

    mutation == "pathogenic",
    "Pathogenic"
  )
]

res_cor[
  ,
  delta_cor_r :=
    mut_cor_r - wt_cor_r
]

res_cor[
  ,
  wt_slope :=
    x_Estimate
]

res_cor[
  ,
  mut_slope :=
    x_Estimate + x_group_Estimate
]


# -------------------------------------------------------------------------
# 9. Classify mutation-associated rewiring
#
# IMPORTANT:
# Significance uses the NOMINAL interaction P value.
# int_p_adj is retained in the output but is not used for classification.
# -------------------------------------------------------------------------

res_cor[
  ,
  rewiring_status := fcase(

    is.na(x_group_Pr.t.) |
      x_group_Pr.t. >= interaction_p_cut,
    "Not significant",

    baseline_association == "Positive" &
      x_group_Estimate > 0,
    "Strengthening",

    baseline_association == "Positive" &
      x_group_Estimate < 0,
    "Weakening",

    baseline_association == "Negative" &
      x_group_Estimate < 0,
    "Strengthening",

    baseline_association == "Negative" &
      x_group_Estimate > 0,
    "Weakening",

    default = "Not significant"
  )
]

res_cor[
  ,
  significant_rewiring :=
    rewiring_status %chin%
      c(
        "Strengthening",
        "Weakening"
      )
]


# -------------------------------------------------------------------------
# 10. Prepare edge-level output
# -------------------------------------------------------------------------

mutation_rewiring_edges <- res_cor[
  ,
  .(
    query,
    query_refseq,
    target,
    target_refseq,

    mutation_class,

    baseline_association,

    wt_n,
    mut_n,

    wt_cor_r,
    wt_cor_p_adj,

    mut_cor_r,
    mut_cor_p_adj,

    delta_cor_r,

    wt_slope,
    mut_slope,

    interaction_estimate =
      x_group_Estimate,

    interaction_se =
      x_group_StdError,

    interaction_p =
      x_group_Pr.t.,

    interaction_p_adj =
      int_p_adj,

    significant_rewiring,
    rewiring_status
  )
]


# -------------------------------------------------------------------------
# 11. Significant strengthening/weakening events
# -------------------------------------------------------------------------

significant_rewiring_edges <-
  mutation_rewiring_edges[
    significant_rewiring == TRUE
  ]


# -------------------------------------------------------------------------
# 12. Summary relative to all baseline associations
#
# fraction:
#
#   number in each rewiring class /
#   total number of associations in the corresponding
#   mutation class and WT baseline association
# -------------------------------------------------------------------------

mutation_rewiring_summary <-
  mutation_rewiring_edges[
    ,
    .(
      n = .N
    ),
    by = .(
      mutation_class,
      baseline_association,
      rewiring_status
    )
  ]

mutation_rewiring_summary[
  ,
  total_associations :=
    sum(n),
  by = .(
    mutation_class,
    baseline_association
  )
]

mutation_rewiring_summary[
  ,
  fraction :=
    n / total_associations
]

mutation_rewiring_summary[
  ,
  percent :=
    100 * fraction
]


# -------------------------------------------------------------------------
# 13. Summary among significant rewiring events only
#
# fraction_among_significant:
#
#   Strengthening or Weakening /
#   all significant rewiring events within the same
#   mutation class and WT baseline association
# -------------------------------------------------------------------------

significant_rewiring_summary <-
  significant_rewiring_edges[
    ,
    .(
      n = .N
    ),
    by = .(
      mutation_class,
      baseline_association,
      rewiring_status
    )
  ]

significant_rewiring_summary[
  ,
  total_significant_rewiring :=
    sum(n),
  by = .(
    mutation_class,
    baseline_association
  )
]

significant_rewiring_summary[
  ,
  fraction_among_significant :=
    n / total_significant_rewiring
]

significant_rewiring_summary[
  ,
  percent_among_significant :=
    100 * fraction_among_significant
]


# -------------------------------------------------------------------------
# 14. Order outputs
# -------------------------------------------------------------------------

mutation_rewiring_summary[
  ,
  mutation_order :=
    match(
      mutation_class,
      c(
        "Benign",
        "Pathogenic"
      )
    )
]

mutation_rewiring_summary[
  ,
  baseline_order :=
    match(
      baseline_association,
      c(
        "Positive",
        "Negative"
      )
    )
]

mutation_rewiring_summary[
  ,
  rewiring_order :=
    match(
      rewiring_status,
      c(
        "Not significant",
        "Strengthening",
        "Weakening"
      )
    )
]

setorder(
  mutation_rewiring_summary,
  mutation_order,
  baseline_order,
  rewiring_order
)

mutation_rewiring_summary[
  ,
  c(
    "mutation_order",
    "baseline_order",
    "rewiring_order"
  ) := NULL
]


significant_rewiring_summary[
  ,
  mutation_order :=
    match(
      mutation_class,
      c(
        "Benign",
        "Pathogenic"
      )
    )
]

significant_rewiring_summary[
  ,
  baseline_order :=
    match(
      baseline_association,
      c(
        "Positive",
        "Negative"
      )
    )
]

significant_rewiring_summary[
  ,
  rewiring_order :=
    match(
      rewiring_status,
      c(
        "Strengthening",
        "Weakening"
      )
    )
]

setorder(
  significant_rewiring_summary,
  mutation_order,
  baseline_order,
  rewiring_order
)

significant_rewiring_summary[
  ,
  c(
    "mutation_order",
    "baseline_order",
    "rewiring_order"
  ) := NULL
]


# -------------------------------------------------------------------------
# 15. Save
# -------------------------------------------------------------------------

fwrite(
  mutation_rewiring_edges,
  file = edge_output_file,
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

fwrite(
  significant_rewiring_edges,
  file = significant_edge_output_file,
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

fwrite(
  mutation_rewiring_summary,
  file = summary_output_file,
  sep = "\t",
  quote = FALSE,
  na = "NA"
)

fwrite(
  significant_rewiring_summary,
  file = significant_summary_output_file,
  sep = "\t",
  quote = FALSE,
  na = "NA"
)


# -------------------------------------------------------------------------
# 16. Reproducibility summary
# -------------------------------------------------------------------------

message(
  "Baseline positive/negative associations: ",
  nrow(
    mutation_rewiring_edges
  )
)

message(
  "Significant mutation-associated rewiring events: ",
  nrow(
    significant_rewiring_edges
  )
)

print(
  mutation_rewiring_summary
)

print(
  significant_rewiring_summary
)

message(
  "Pan-cancer mutation-associated rewiring analysis completed."
)
